SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='HS_Scores_Duplicate_Archive' ORDER BY ORDINAL_POSITION; SELECT COLUMN_NAME, IS_NULLABLE, COLUMNPROPERTY(OBJECT_ID('dbo.HS_Scores'),COLUMN_NAME,'IsComputed') AS Computed FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='HS_Scores' ORDER BY ORDINAL_POSITION;
